import {
  forwardRef,
  useEffect,
  useRef,
  type CSSProperties,
  type HTMLAttributes,
  type ReactNode,
} from "react";

import { useReducedMotion } from "./hooks/use-reduced-motion";
import { motionTokens } from "./tokens";

export interface RevealProps extends Omit<
  HTMLAttributes<HTMLDivElement>,
  "children"
> {
  children: ReactNode;
  /** Direction the content reveals from. @default "up" */
  direction?: "up" | "down" | "left" | "right" | "none";
  /** Distance in px. @default 12 */
  distance?: number;
  /** Delay in ms. @default 0 */
  delay?: number;
  /** Disable the reveal (content appears instantly). @default false */
  disabled?: boolean;
  /** Animate only once (default) or every time it enters the viewport. */
  once?: boolean;
  /** Threshold for IntersectionObserver. @default 0.15 */
  threshold?: number;
}

/**
 * Reveal — an in-view entrance animation.
 *
 * Implementation: `IntersectionObserver` toggles a `data-revealed` attribute;
 * the actual transition is CSS (transform + opacity), compositor-only.
 *
 * Reduced motion: the effect is disabled entirely. Content appears
 * immediately at full opacity with no transform.
 *
 * Performance: no JavaScript animation loop. The observer only fires on
 * enter/leave. The transition runs on the compositor.
 */
export const Reveal = forwardRef<HTMLDivElement, RevealProps>(function Reveal(
  {
    children,
    direction = "up",
    distance = 12,
    delay = 0,
    disabled = false,
    once = true,
    threshold = 0.15,
    style,
    ...rest
  },
  ref,
) {
  const reduced = useReducedMotion();
  const enabled = !disabled && !reduced;
  const innerRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    if (!enabled) return;
    const el = innerRef.current;
    if (!el || typeof IntersectionObserver === "undefined") {
      // No IO support — show immediately.
      return;
    }
    const io = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting) {
            entry.target.setAttribute("data-revealed", "true");
            if (once) io.unobserve(entry.target);
          } else if (!once) {
            entry.target.removeAttribute("data-revealed");
          }
        }
      },
      { threshold },
    );
    io.observe(el);
    return () => io.disconnect();
  }, [enabled, once, threshold]);

  const initialTransform = (() => {
    if (!enabled) return "none";
    switch (direction) {
      case "up":
        return `translate3d(0, ${distance}px, 0)`;
      case "down":
        return `translate3d(0, -${distance}px, 0)`;
      case "left":
        return `translate3d(${distance}px, 0, 0)`;
      case "right":
        return `translate3d(-${distance}px, 0, 0)`;
      default:
        return "none";
    }
  })();

  const baseStyle: CSSProperties = {
    opacity: enabled ? 0 : 1,
    transform: initialTransform,
    transition: `opacity ${motionTokens.duration.normal}ms var(--ease-standard, ease-out) ${delay}ms, transform ${motionTokens.duration.normal}ms var(--ease-standard, ease-out) ${delay}ms`,
    willChange: enabled ? "opacity, transform" : "auto",
    ...style,
  };

  const revealedStyle: CSSProperties = {
    opacity: 1,
    transform: "none",
  };

  return (
    <>
      <style>{`
        [data-digital-reveal][data-revealed="true"] {
          opacity: 1 !important;
          transform: none !important;
        }
      `}</style>
      <div
        {...rest}
        ref={(node) => {
          innerRef.current = node;
          if (typeof ref === "function") ref(node);
          else if (ref) ref.current = node;
        }}
        data-digital-reveal=""
        style={enabled ? baseStyle : { ...baseStyle, ...revealedStyle }}
      >
        {children}
      </div>
    </>
  );
});

import {
  useEffect,
  useRef,
  type CSSProperties,
  type MutableRefObject,
} from "react";

/**
 * Reads the first child's computed border-radius and applies it to the
 * wrapper element. This lets motion wrappers (Glow, Pulse, Spotlight)
 * automatically match the wrapped element's rounded corners without
 * requiring the user to pass a `className` for the radius.
 *
 * @returns A ref to attach to the wrapper element.
 */
export function useInheritedRadius<T extends HTMLElement = HTMLElement>(
  style?: CSSProperties,
): MutableRefObject<T | null> {
  const ref = useRef<T | null>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    const child = el.firstElementChild as HTMLElement | null;
    if (!child) return;

    const childRadius = getComputedStyle(child).borderRadius;
    if (childRadius && childRadius !== "0px") {
      el.style.borderRadius = childRadius;
    }
  }, [style]);

  return ref;
}

import { useEffect, useState } from "react";

/**
 * Returns `true` when the user has requested reduced motion via the OS / browser.
 *
 * All IonBit UI motion primitives use this to self-disable. Components should
 * never animate transform/opacity in a way that distracts under reduced motion.
 */
export function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState<boolean>(() => {
    if (typeof window === "undefined" || !window.matchMedia) return false;
    return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  });

  useEffect(() => {
    if (typeof window === "undefined" || !window.matchMedia) return;
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const handler = (e: MediaQueryListEvent) => setReduced(e.matches);
    mq.addEventListener("change", handler);
    return () => mq.removeEventListener("change", handler);
  }, []);

  return reduced;
}

/**
 * IonBit UI — Motion tokens
 *
 * The single source of truth for timing, easing, spring, and intensity.
 * Components and primitives reference these; they do not hardcode values.
 *
 * These mirror the CSS variables in @ionbit-ui/tokens so JS-driven
 * animations (Motion) and CSS-driven animations stay in sync.
 */

export const motionTokens = {
  duration: {
    fast: 140,
    normal: 220,
    slow: 420,
  },
  easing: {
    standard: [0.2, 0.8, 0.2, 1] as const,
    emphasized: [0.3, 0, 0, 1] as const,
    exit: [0.4, 0, 1, 1] as const,
  },
  spring: {
    magnetic: { stiffness: 200, damping: 15, mass: 0.3 },
    gentle: { stiffness: 120, damping: 20, mass: 0.4 },
  },
  intensity: {
    glow: 0.6,
    spotlight: 0.4,
    magnetic: 0.25,
  },
} as const;

export type MotionTokens = typeof motionTokens;
